# numbers_e52.jl: the macros of E52 (results/e52_admm.json, HPG runs), consensus ADMM with one agent per vehicle
# (the fleet program) against consensus ADMM with one agent per team (the quotient program, the rows of E26's
# coherent drone/car fleet), written to preamble/numbers_e52.tex. Not registered with gen_numbers.jl; main.tex
# inputs the generated file with \InputIfFileExists.
#
#   julia --project=env scripts/resolution/numbers_e52.jl
#
# Macro names: \cnQad<Metric><Arm>[B<budget>]<Size>   (distinct from numbers.tex's \cnAdmm*)
#   Arm     Full (one agent per vehicle), Team (one agent per team, the quotient program)
#   Budget  One, Five, Twenty (ADMM iterations per sample, warm started)
#   Metric  Cost (closed-loop cost over coordinated MPC, median over seeds), CostMax (worst seed),
#           ParMs / SeqMs (median over seeds of the per-seed median parallel / one-core ms per sample),
#           Floats (floats exchanged per sample, median), FloatsRatio (Full over Team), SeqRatio / ParRatio
#           (Full over Team), Rounds (message exchanges per sample)
#           ItThree / ItFour (cold-start iterations to 1e-3 / 1e-4 relative suboptimality, Min and Max over seeds
#           and the traced steps 0, 10, 20; Med is the median of all of them)
#   Size    K (1024 vehicles), Big (4096 vehicles)

using JSON, Printf, Statistics

function sci52(x; d = 1)
    x == 0 && return "0"
    e = floor(Int, log10(abs(x))); m = x / 10.0^e
    s = @sprintf("%.*f", d, m)
    if parse(Float64, s) >= 10; m /= 10; e += 1; s = @sprintf("%.*f", d, m); end
    return "\\ensuremath{$(s)\\times10^{$(e)}}"
end
ms52(x) = x < 100 ? @sprintf("%.1f", x) : string(round(Int, x))        # ms: one decimal below 100, else integer
cost52(x) = @sprintf("%.4f", x)                                        # cost ratios to four decimals
int52(x) = string(round(Int, x))
ratio52(x) = x < 10 ? @sprintf("%.1f", x) : string(round(Int, x))

const BUDGETS_E52 = (1 => "One", 5 => "Five", 20 => "Twenty")
const ARMS_E52 = ("full" => "Full", "quot" => "Team")
const SIZES_E52 = ("1024" => "K", "4096" => "Big")

function write_e52_numbers(root = normpath(joinpath(@__DIR__, "..", "..")))
    E = JSON.parsefile(joinpath(root, "results", "e52_admm.json"))
    # provenance of the parts behind these macros (the 1024 and 4096 sizes only)
    metas = [p["meta"] for (n, _) in SIZES_E52 if haskey(E["sizes"], n) for p in E["sizes"][n]["parts"] if p["meta"] !== nothing]
    M = Dict(k => sort!(unique([string(get(m, f, "")) for m in metas])) for (k, f) in
             ("jobs" => "job", "hosts" => "host", "cpus" => "cpu", "partition" => "partition", "exclusive" => "exclusive",
              "commit" => "commit", "teammpc_version" => "teammpc_version", "teammpc_repo_rev" => "teammpc_repo_rev"))
    lines = String["% GENERATED by scripts/resolution/numbers_e52.jl from results/e52_admm.json; do not edit by hand.",
                   "% Regenerate with `julia --project=env scripts/resolution/numbers_e52.jl`.",
                   "% HPG jobs $(join(get(M, "jobs", []), ", ")); hosts $(join(get(M, "hosts", []), ", ")); CPU $(join(get(M, "cpus", []), ", "))",
                   "% partition $(join(get(M, "partition", []), ", ")), exclusive $(join(get(M, "exclusive", []), ", ")); commit $(join(get(M, "commit", []), ", "))",
                   "% TeamMPC $(join(get(M, "teammpc_version", []), ", ")) at $(join(get(M, "teammpc_repo_rev", []), ", "))", ""]
    put(name, val, meaning) = (push!(lines, "% $meaning"); push!(lines, "\\newcommand{\\$name}{$val}"))
    first_ = true
    for (n, z) in SIZES_E52
        haskey(E["sizes"], n) || continue
        S = E["sizes"][n]; L = S["loops"]; T = S["trace"]
        if first_
            put("cnQadSteps", string(S["parts"][1]["meta"]["steps"]), "closed-loop steps per run")
            put("cnQadPeriodMs", int52(E["period_ms"]), "sampling period (ms)")
            first_ = false
        end
        put("cnQadSeeds$z", string(length(S["seeds"])), "$n vehicles: seeds")
        put("cnQadN$z", n, "$n vehicles: agents of the full ADMM (one per vehicle)")
        put("cnQadTeams$z", int52(S["rows"]), "$n vehicles: agents of the team ADMM (one per team)")
        put("cnQadRhoFull$z", @sprintf("%g", S["rho"]["full"]), "$n vehicles: ADMM penalty, one agent per vehicle (tuned on seed 1)")
        put("cnQadRhoTeam$z", @sprintf("%g", S["rho"]["quot"]), "$n vehicles: ADMM penalty, one agent per team (tuned on seed 1)")
        put("cnQadCoordMs$z", ms52(S["coord_ms_med"]), "$n vehicles: coordinated MPC (central, one core), median ms per sample")
        for (b, bz) in BUDGETS_E52
            F = L["full_b$b"]; Q = L["quot_b$b"]
            for (arm, az) in ARMS_E52
                D = L["$(arm)_b$b"]
                put("cnQadCost$(az)B$(bz)$z", cost52(D["cost_ratio_med"]), "$n, $b iterations per sample, $arm: closed-loop cost over coordinated MPC, median over seeds")
                put("cnQadCostMax$(az)B$(bz)$z", cost52(D["cost_ratio_max"]), "the same, worst seed")
                put("cnQadParMs$(az)B$(bz)$z", ms52(D["par_ms_med"]), "$n, $b iterations, $arm: parallel ms per sample (one core per agent, no latency), median")
                put("cnQadSeqMs$(az)B$(bz)$z", ms52(D["seq_ms_med"]), "$n, $b iterations, $arm: sequential ms per sample (all agents on one core), median")
                put("cnQadFloats$(az)B$(bz)$z", sci52(D["floats_med"]), "$n, $b iterations, $arm: floats exchanged per sample, median")
                put("cnQadRounds$(az)B$(bz)$z", int52(D["rounds"]), "$n, $b iterations, $arm: message rounds per sample")
            end
            put("cnQadFloatsRatioB$(bz)$z", ratio52(F["floats_med"] / Q["floats_med"]), "$n, $b iterations: floats per sample, one agent per vehicle over one per team")
            put("cnQadSeqRatioB$(bz)$z", ratio52(F["seq_ms_med"] / Q["seq_ms_med"]), "$n, $b iterations: sequential time, one agent per vehicle over one per team")
            put("cnQadParRatioB$(bz)$z", ratio52(F["par_ms_med"] / Q["par_ms_med"]), "$n, $b iterations: parallel time, one agent per vehicle over one per team")
        end
        for (a, az) in ("0.001" => "Three", "0.0001" => "Four"), (arm, mz) in ARMS_E52
            its = [k for key in keys(T) if startswith(key, arm * "_") for k in T[key][a]["iter_seeds"]]
            unreached = count(<(0), its)
            ok = filter(>(0), its)
            put("cnQadIt$(az)$(mz)Min$z", int52(minimum(ok)), "$n, cold start, $arm: fewest iterations to $a relative suboptimality (seeds x steps 0, 10, 20)")
            put("cnQadIt$(az)$(mz)Max$z", int52(maximum(ok)), "the same, most")
            put("cnQadIt$(az)$(mz)Med$z", int52(median(ok)), "the same, median")
            put("cnQadIt$(az)$(mz)Unreached$z", string(unreached), "the same, traces that did not reach $a")
        end
    end
    out = joinpath(root, "preamble", "numbers_e52.tex")
    open(io -> println(io, join(lines, "\n")), out, "w")
    println("wrote $out ($(count(l -> startswith(l, "\\newcommand"), lines)) macros)")
    return out
end

if abspath(PROGRAM_FILE) == @__FILE__
    write_e52_numbers()
end
